from common import build as _b, btn

P0 = 75 / 5674                       # the shared FPD chance of app + branch (H0)
APP, BR, PA = [41, 2411], [34, 3263], [16, 1425]
L_AB = [("app", "приложение"), ("branch", "филиалы")]
AX_AB = ("gap app − branch, points", "разрыв приложение − филиалы, пункты")
LUCKW = {"thing": ("Luck worlds", "Миров случая"), "axis": AX_AB, "obs": ("real gap", "реальный разрыв")}
LW = {"exp": ("one shared chance", "один общий шанс"), "real": ("real gap", "реальный разрыв"), "axis": AX_AB,
      "world": ("Luck world", "Мир случая")}
# FPD % of the same ten branches, 2025 and 2026 (f, pivot by branch_name and year; mean change −0.58, paired t −2.56)
W10 = [[1.57, 0.89], [3.20, 1.99], [1.22, 0.82], [1.95, 0.49], [1.12, 0.66], [0.87, 0.75], [1.94, 1.44], [0.55, 1.54], [1.60, 1.03], [2.09, 0.72]]
NAMES = (["Andijan", "Bukhara", "Fergana", "Namangan", "Nukus", "Samarkand", "Tashkent C.", "Tashkent N.", "Tashkent S.", "Termez"],
         ["Андижан", "Бухара", "Фергана", "Наманган", "Нукус", "Самарканд", "Ташкент Ц.", "Ташкент С.", "Ташкент Ю.", "Термез"])
REAL_OR_LUCK = (["real", "luck"], ["настоящая разница", "случайность"])


def gw(axis_en, axis_ru):   # the game's words for one round
    return {"exp": LW["exp"], "real": LW["real"], "axis": (axis_en, axis_ru), "world": LW["world"]}


def roll(n, en, ru, rep=1):
    return btn(n, en, ru, rep, do="roll")


def sample(n, en, ru, rep=1):
    return btn(n, en, ru, rep, do="sample")


